mapper.select:
SELECT s.* FROM subject s

    JOIN subject_tag st ON s.id = st.subject_id AND st.name IN

        #{tag}




        AND (s.name LIKE CONCAT('%', #{keyword}, '%')
             OR s.name_cn LIKE CONCAT('%', #{keyword}, '%'))


        AND s.score >= #{scoreMin}


        AND s.score <= #{scoreMax}


        AND s.air_date >= CONCAT(#{year}, '-01-01')
        AND s.air_date <= CONCAT(#{year}, '-12-31')


        AND s.air_weekday = #{weekday}



    GROUP BY s.id
    HAVING COUNT(DISTINCT st.name) = ${tagList.size}

ORDER BY

    IF(s.name_cn LIKE CONCAT('%', #{keyword}, '%'), 0, 1),

${sortField} ${order}

SELECT s.id AS subjectId, s.name, s.name_cn AS nameCn, MATCH(d.title, d.aliases, d.lexical_text) AGAINST (#{query} IN NATURAL LANGUAGE MODE) AS lexicalScore FROM search_document d INNER JOIN search_index_release r ON r.index_version = d.index_version AND r.profile_version = d.profile_version AND r.status = 'ACTIVE' AND r.active_slot = 1 INNER JOIN subject s ON s.id = d.entity_id WHERE d.entity_kind = 'SUBJECT' AND d.index_version = #{indexVersion} AND d.source_active = 1 AND s.type = 2 AND s.nsfw = 0 AND s.import_status = 1 AND MATCH(d.title, d.aliases, d.lexical_text) AGAINST (#{query} IN NATURAL LANGUAGE MODE) > 0
AND EXISTS ( SELECT 1 FROM subject_tag st WHERE st.subject_id = s.id AND st.name = #{tag} )
AND s.score >= #{scoreMin}
AND s.score <= #{scoreMax}
AND s.air_date >= CONCAT(#{year}, '-01-01') AND s.air_date <= CONCAT(#{year}, '-12-31')
AND s.air_weekday = #{weekday}
AND s.id IN
#{subjectId}
ORDER BY lexicalScore DESC, s.id ASC LIMIT #{limit}
